//! Content pin for the generated analyzer registry table
//! (`data/analyzer-codes.tsv`).

use std::path::Path;

/// blake3 digest of the pinned analyzer registry table (the upstream
/// analyzer registry of the 3.13.7 conformance pin, generated by
/// `tools/upstream-gen`'s `analyzer-codes-gen` from the pinned SDK tree —
/// 1150 registry consts folding to 979 name rows; see the TSV header for
/// the source identity).
///
/// Any content edit changes the generated registry: regenerate against
/// the SDK tree of record (`DARTQ_SDK_SRC=<dart-sdk-tree> cargo run -p
/// upstream-gen --bin analyzer-codes-gen`), re-verify the
/// tier-transition tests, then re-pin this digest deliberately. This
/// test exists so a wrong table cannot ship green.
const PINNED_BLAKE3: &str = "eaa3c0f284b2ea07345e78b8681d910337bb7146beaa9a2a440f76f996b2d69d";

#[test]
fn analyzer_codes_tsv_matches_pinned_blake3() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("data/analyzer-codes.tsv");
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    let actual = blake3::hash(&bytes).to_hex().to_string();
    assert_eq!(
        actual, PINNED_BLAKE3,
        "analyzer-codes.tsv drifted from the pinned snapshot (actual blake3: {actual}); \
         regenerate with tools/upstream-gen against the SDK tree of record, then re-pin \
         deliberately"
    );
}
